// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BillingNotification) predicate.BillingNotification {
	return predicate.BillingNotification(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BillingNotification) predicate.BillingNotification {
	return predicate.BillingNotification(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BillingNotification) predicate.BillingNotification {
	return predicate.BillingNotification(sql.NotPredicates(p))
}
